--
-- Table structure for table `perfumes`
--

DROP TABLE IF EXISTS `perfumes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `perfumes` (
  `id` int NOT NULL AUTO_INCREMENT,
  `name` varchar(100) NOT NULL,
  `brand_id` int NOT NULL,
  `rating_id` int NOT NULL,
  `description` text NOT NULL,
  `gender_id` enum('men','women','unisex') CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL,
  `country_id` int NOT NULL,
  `year` int NOT NULL,
  PRIMARY KEY (`id`),
  KEY `perfumes_rating_info_FK` (`rating_id`),
  KEY `perfumes_brand_FK` (`brand_id`),
  KEY `perfumes_country_info_fk` (`country_id`),
  FULLTEXT KEY `description` (`description`),
  CONSTRAINT `perfumes_brand_FK` FOREIGN KEY (`brand_id`) REFERENCES `brand_info` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `perfumes_country_info_fk` FOREIGN KEY (`country_id`) REFERENCES `country_info` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `perfumes_rating_info_FK` FOREIGN KEY (`rating_id`) REFERENCES `rating_info` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4662 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

